import android.app.*;import android.content.*;import android.graphics.Color;import android.os.*;import android.view.*;import android.widget.*;
public class OverlayService extends Service {WindowManager wm;View v;public IBinder onBind(Intent i){return null;}public int onStartCommand(Intent i,int f,int s){if(v!=null)return START_STICKY;wm=(WindowManager)getSystemService(WINDOW_SERVICE);LinearLayout box=new LinearLayout(this);box.setOrientation(LinearLayout.VERTICAL);box.setPadding(18,12,18,12);box.setBackgroundColor(Color.rgb(18,28,46));TextView t=new TextView(this);t.setText("AVIATOR ANALYZER\nMonitoring overlay\nHistorical analysis only");t.setTextColor(Color.WHITE);box.addView(t);TextView close=new TextView(this);close.setText("\n× Close");close.setTextColor(Color.rgb(57,208,200));close.setOnClickListener(x->stopSelf());box.addView(close);int type=Build.VERSION.SDK_INT>=26?WindowManager.LayoutParams.TYPE_APPLICATION_OVERLAY:WindowManager.LayoutParams.TYPE_PHONE;WindowManager.LayoutParams lp=new WindowManager.LayoutParams(280,WindowManager.LayoutParams.WRAP_CONTENT,type,WindowManager.LayoutParams.FLAG_NOT_FOCUSABLE,-3);lp.gravity=Gravity.TOP|Gravity.END;lp.x=16;lp.y=160;v=box;wm.addView(v,lp);return START_STICKY;}public void onDestroy(){if(v!=null)wm.removeView(v);super.onDestroy();}}
